## 3. Result-Generation Logic (form data → recommendation)

The core recommendation is computed by the inline `evaluate()` function (and supporting types/defaults) in the Compass page.

Source: `client/src/pages/OvulationInductionCompass.tsx`

```typescript
type AnovulationCause = "pcos" | "hypothalamic" | "hyperprolactinemia" | "thyroid" | "poi" | "unexplained";

interface OIInputs {
  anovulationCause: AnovulationCause;
  femaleAge: number;
  bmi: number;
  priorLetrozoleTrials: number;
  priorClomipheneTrials: number;
  priorMetforminTrials: number;
  priorGonadotropinTrials: number;
  tubalPatency: boolean;
  normalSemenAnalysis: boolean;
  hyperprolactinemiaTreated: boolean;
  thyroidTreated: boolean;
}

const defaultInputs: OIInputs = {
  anovulationCause: "pcos", femaleAge: 0, bmi: 0,
  priorLetrozoleTrials: 0, priorClomipheneTrials: 0, priorMetforminTrials: 0,
  priorGonadotropinTrials: 0, tubalPatency: true, normalSemenAnalysis: true,
  hyperprolactinemiaTreated: false, thyroidTreated: false,
};

function evaluate(inputs: OIInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Legro RS, et al. Diagnosis and Treatment of Polycystic Ovary Syndrome: An Endocrine Society Clinical Practice Guideline. J Clin Endocrinol Metab. 2013;98(12):4565-4592.",
    "Thessaloniki ESHRE/ASRM-Sponsored PCOS Consensus Workshop Group. Consensus on infertility treatment related to polycystic ovary syndrome. Fertil Steril. 2008;89(3):505-522.",
    "Legro RS, et al. Letrozole versus clomiphene for infertility in the polycystic ovary syndrome. N Engl J Med. 2014;371(2):119-129.",
    "Practice Committee of the ASRM. Use of clomiphene citrate in infertile women. Fertil Steril. 2013;100(2):341-348.",
  ];

  let recommendation = "not_indicated";
  let procedure = "";
  let cor = "I";
  let loe = "A";

  if (inputs.anovulationCause === "hyperprolactinemia" && !inputs.hyperprolactinemiaTreated) {
    recommendation = "not_indicated";
    procedure = "Treat hyperprolactinemia first (dopamine agonist)";
    cor = "I"; loe = "A";
    rationale.push("Hyperprolactinemia: treat with cabergoline or bromocriptine first. Ovulation induction before treating hyperprolactinemia is not indicated.");
  } else if (inputs.anovulationCause === "thyroid" && !inputs.thyroidTreated) {
    recommendation = "not_indicated";
    procedure = "Treat thyroid disorder first";
    cor = "I"; loe = "A";
    rationale.push("Thyroid disorder: normalize thyroid function before ovulation induction. Hypothyroidism and hyperthyroidism both impair ovulation.");
  } else if (inputs.anovulationCause === "poi") {
    recommendation = "not_indicated";
    procedure = "Ovulation induction not effective for POI — consider donor oocyte";
    cor = "III"; loe = "A";
    warnings.push("Premature ovarian insufficiency (POI): ovulation induction is not effective. Spontaneous ovulation occurs in only 5–10% of cases. Donor oocyte IVF is the most effective treatment.");
  } else if (inputs.anovulationCause === "pcos") {
    if (inputs.priorLetrozoleTrials === 0 && inputs.priorClomipheneTrials === 0) {
      recommendation = "indicated";
      procedure = "Letrozole (first-line for PCOS) — 2.5–7.5 mg days 3–7";
      cor = "I"; loe = "A";
      rationale.push("PCOS: letrozole is first-line ovulation induction per ASRM/Endocrine Society (Legro et al., NEJM 2014 — higher live birth rate than clomiphene).");
    } else if (inputs.priorLetrozoleTrials < 6) {
      recommendation = "indicated";
      procedure = `Continue letrozole trials (${inputs.priorLetrozoleTrials} completed, up to 6 recommended)`;
      cor = "I"; loe = "A";
      rationale.push("Continue letrozole — up to 6 cycles are appropriate before escalating to gonadotropins or IVF.");
    } else if (inputs.priorGonadotropinTrials === 0) {
      recommendation = "indicated";
      procedure = "Gonadotropin ovulation induction (FSH/LH) — step-up protocol";
      cor = "I"; loe = "A";
      rationale.push("Failed 6+ letrozole cycles: gonadotropin ovulation induction is the next step per ASRM guidelines.");
      warnings.push("Gonadotropins carry higher risk of multiple gestation and OHSS. Careful monitoring with serial ultrasound required.");
    } else {
      recommendation = "consider";
      procedure = "Consider IVF — multiple OI failures";
      cor = "IIa"; loe = "B";
      rationale.push("Multiple failed ovulation induction cycles: IVF may be more cost-effective and efficient at this point.");
    }
    if (inputs.bmi >= 30) {
      warnings.push(`BMI ${inputs.bmi}: weight loss of 5–10% may restore ovulation in PCOS. Lifestyle modification should be concurrent with OI.`);
    }
  } else {
    recommendation = "indicated";
    procedure = "Ovulation induction — individualized protocol";
    cor = "IIa"; loe = "B";
    rationale.push("Anovulation identified: ovulation induction is indicated after treating reversible causes.");
  }

  return { recommendation, procedure, cor, loe, warnings, rationale, references };
}
